mapper.select:
select pro.P_Name as pName, pro.P_Code as pCode, con.Con_Name as conName, con.Con_Code as conCode, mn.* from Night_Construction_Filing mn left join Pre_Project pro on pro.P_Id=mn.P_Id left join Con_Contract con on con.Con_Id=mn.Con_Id ${params.authSql}
and mn.state=#{params.state}
and mn.P_Id=#{params.pId}
and mn.Con_Id=#{params.conId}
and INSTR(mn.Ncf_Leader,#{params.ncfLeader})
and INSTR(mn.Ncf_Leader_Phone,#{params.ncfLeaderPhone})
and INSTR(mn.Ncf_Area_Section,#{params.ncfAreaSection})
and INSTR(mn.Ncf_Worker,#{params.ncfWorker})
and INSTR(mn.Ncf_Worker_Phone,#{params.ncfWorkerPhone})
and INSTR(mn.Ncf_Side,#{params.ncfSide})
and INSTR(mn.Ncf_Side_Phone,#{params.ncfSidePhone})
and INSTR(mn.create_uname,#{params.createUname})
and likePname(#{params.pName},mn.P_Id)=true
and INSTR(pro.P_Name,#{params.pName})
and INSTR(pro.P_Code,#{params.pCode})
and INSTR(con.Con_Name,#{params.conName})
and INSTR(con.Con_Code,#{params.conCode})
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time desc
